<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Http\Requests\StorePaketCuciRequest;use App\Http\Requests\UpdatePaketCuciRequest;use App\Models\PaketCuci;use App\Services\MasterAuditService;use Illuminate\Http\RedirectResponse;use Illuminate\View\View;
class PaketCuciController extends Controller { public function index():View{return view('admin.paket-cuci.index',['items'=>PaketCuci::orderBy('nama_paket')->paginate(10)]);} public function create():View{return view('admin.paket-cuci.create',['item'=>new PaketCuci(['status'=>'aktif','harga'=>0])]);} public function store(StorePaketCuciRequest $r,MasterAuditService $a):RedirectResponse{$i=PaketCuci::create($r->validated());$a->record('create','paket_cuci',$i->id_paket,'Menambah paket cuci');return redirect()->route('admin.paket-cuci.index');} public function show(PaketCuci $paketCuci):View{return view('admin.paket-cuci.show',['item'=>$paketCuci]);} public function edit(PaketCuci $paketCuci):View{return view('admin.paket-cuci.edit',['item'=>$paketCuci]);} public function update(UpdatePaketCuciRequest $r,PaketCuci $paketCuci,MasterAuditService $a):RedirectResponse{$paketCuci->update($r->validated());$a->record('update','paket_cuci',$paketCuci->id_paket,'Mengubah paket cuci');return redirect()->route('admin.paket-cuci.show',$paketCuci);} public function toggle(PaketCuci $paketCuci,MasterAuditService $a):RedirectResponse{$x=$paketCuci->status==='aktif'?'nonaktif':'aktif';$paketCuci->update(['status'=>$x]);$a->record('status','paket_cuci',$paketCuci->id_paket,'Status menjadi '.$x);return back();} }
